INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1474257-ics381', 'stk-user10899', 'ICS 381', 'info', '{"desc": "لا تاخذ هالكورس قبل لا تاخذ ICS202. على انه مكتوب في سلايدات هالمادة ان الICS202 prerequest له مادري ليش الدبارتمنت ما عدها هالشي\nالكورس الي يتقدم في جامعتنا هو نفس الكورس الي في هالصفحة هذي.\nكنا نشتغل على لعبة pacman. طبعا كانت مصممة وجاهزة بلغة البايثون واحنا نخلي الpacman يتحرك ويهرب وياكل و…\nالهوموركات كانت في قروبات.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ics-381-principles-of-artificial-intelligence/120849/4", "user": "user10899", "ts": 1496263437000, "tid": 120849, "pn": 4}}', 1496263437000, 1794826863, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1493016-ics381', 'stk-walo0od', 'ICS 381', 'info', '{"desc": "Up\nشباب يا ليت اللي أخذ المادة من قبل يجاوبني، إلى أي درجة المادة صعبة؟ هل هي مستحيلة تجيب فيها قريد عالي؟ مع العلم أن مستواي في الماث مو مرة جيد.\nيا ليت تقييم للمادة لا هنتوا.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ics-381-principles-of-artificial-intelligence/120849/5", "user": "Walo0od", "ts": 1527303334000, "tid": 120849, "pn": 5}}', 1527303334000, 1794826863, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p58779-ics381', 'stk-user896', 'ICS 381', 'info', '{"desc": "مرحبا يا شبيبه…\nأخوي دريم أنا أخذتها في الصيف الماضي…\nوبصراحة أقول لك… المادة مثل بعض مواد ال ICS يعني مال أمها داعي…(هذا برأيي المتواضع)\nبس من ناحية السهولة… فهي سهلة جداً… وزي ما قلت أنت… أن المادة فيها كثير من ال251 وال252…\nلكن بعدين بتدخلوا في البرولوغ… وبعدين تبدأ تتعمق أكثر فأكثر…\nالبرولوغ كلغة بحد ذاتها سهلة بس يبغالها شوية ممارسة…\nلكن المشكلة أن البروجكت نفسه معقد… بس لحسن الحظ كانوا نصف الطلاب متعقدين من البروجكت… مما جعل كريشنا يساعدنا شوي;) …\nوهو كمدرس طيب جداً(وأظنك لاحظت هالشي)… وأسئلته زي ما قال لك الدكتور… يعني على قد شرحه…\nاللهم إلا في الفاينل… يعني شوي أصعب…\nلكن مع ذلك خرجت بجريد ما كنت أتوقعه(يعني أحسن من توقعي)…\nومن ناحية الشرح… فبصراحة أنا استغربت انك تكلمت عليه بقوة… وهذا اللي خلاني ما أعلق من البداية لأني قلت يمكن شفتو منه ما لم أره أنا:D\nعموماً…\nانشاء الله أكون أعطيتك شيء مفيد:)\n\nالقبطان;)", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ics381/39861/5", "user": "user896", "ts": 1095272238000, "tid": 39861, "pn": 5}}', 1095272238000, 1794826863, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p979013-ics381', 'stk-one_egyptian', 'ICS 381', 'info', '{"desc": "السلام عليكم شباب\nهل في احد سبق ودرس المادة هذي خصوصا مع الدكتور Lahouari Ghouti\n\nلان بصراحه مو فاهم ولا حرف في الكلاس وهذي اول مره شي زي كذا يحصل معي 🤪\n\nفي العاده انا اعتمد اعتماد تام على شرح الدكتور … لكن هالمره ما اظن انا ولا غيري فاهمين شي 😡 😡\n\nوالدكتور ما غير يزاعق علينا كل ما سال شي ولا احد جاوبه\n\nابسط المفاهيم من 202 خلاها جداااا معقده\n\nاللي عنده اي خلفيه عن المادة ياريت لو يقولنا كيف نتعامل معها\n\nلان للاسف حذف الماده مستحيل … واللا بشيل 21 ساعه الترم القادم", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ics-381-principles-of-artificial-intlligence/119679/1", "user": "One_Egyptian", "ts": 1328273713000, "tid": 119679, "pn": 1}}', 1328273713000, 1794826863, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p980749-ics381', 'stk-abdu1002', 'ICS 381', 'info', '{"desc": "أنا أخذت المادة الفصل الماضي… هي مادة ثقيلة ، لكن!\nعليك بقراءة الكتاب في الفصول التي تأخذونها فهو جدا واضح ومفهوم أكثر من شرح الدكتور الذي يثير الرعب في النفوس … لا تعتمد على السلايدات!!\nعليك أيضا أن تحاول جاهدا حل الواجبات وخصوصا الكتابية… فأسلوبها شبيه جدا بأسلوب الإختبارات التي يقدمها الدكتور. لا تهمل الواجبات البرمجية فهي مهمة جدا أيضا.\nركز على الكويزات أيضا فبعض أفكارها تأتي في الإختبار…\nمن ناحية الإختبارات فكنا ننظر إليها برعب شديد… كنت أخرج من الإختبار أشعر أنني سآخذ 0 حرفيييا … لكن في الحقيقة حل الأسئلة يكون سهل جدا في الغالب وأجد في النهاية درجة لا بأس بها.\n\nهذه إحدى المواد التي كنت أعتقد أنني سأحذفها لا محالة … لكنني الحمد لله أنهيتها وبدرجة ممتازة جدا.\nلا تنسى الاستعانة بالله … حاول الجلوس في المقدمة وحاول أن تلقي على الدكتور بأسئلة ذكية وحتى لو لم تفهم فقرة فاسأله … سيحاول شرحها بدقة.\nأحد الطلاب كان أخذ فيها a+ -ماشاء الله- مع عرفات صار يحضر معانا المحاضرات فوجد المادة مختلفة تمااااما عما أخذه مع دكتور عرفات من خرابيط.\nصراحة هي إحدى المواد التي تعلمت فيها الشيء الكثير… فأنصحك أن لا تضيعها على نفسك.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ics-381-principles-of-artificial-intlligence/119679/6", "user": "Abdu1002", "ts": 1328525679000, "tid": 119679, "pn": 6}}', 1328525679000, 1794826863, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-some001-ics381', 'stk-some001', 'ICS 381', 'doc', '{"docs": [{"id": "stk-dr-f98299", "n": "Dr. El-Sayed El-Alfy", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "طبعا الي بقوله صار معي … يمكن ما صار مع غيري\nترم 121 - ics381\n**التحضير :**ما يفوت دقيقة وحدة من الكلاس ومن نص الترم لنهايته كل كلاس ياخذ من 10-25 دقيقة زيادة ع الكلاس كان يستغل فترة البريك يقول ما عندكم حاجة تسووها\n(مع انه كان عندي كلاس على 12:25 كنت اطلع من عنده وادخل الكلاس الي بعده … مافي بريك عندي على ايامها)\nالتحضير يومي في نهاية الكلاس ويحضر في نهاية الكلاس … اذا كان ودك تطلع بدري لاي سبب بيروح عليك التحضير\n\n**طريقة الشرح :**ما ادري عن الشباب الي فوق اشوف بعضهم يقول ممتاز وكذا … لكن …\nوالله اني ما دخلت الكلاس يوم وطلعت وانا فاهم الي بيوصله 100% يمكن كلاس ولا كلاسين طول الترم … 90% من الكلاسات ادخل واطلع ب 0 فايدة 100 مضيعة للوقت …\nطبعا كنت ماخذ معاه كورسات المتريال مشترك بينهم فـ حتى اذا كان فيه شي جديد علي اكون ماخذه ف الكورسات الثانية وفاهمه هناك واجي هنا اهز راسي مسوي فاهم عليه\nممل ومنوم بشكل مو طبيعي … وهذي اسوأ نوعية من المدرسين الي ممكن تشوفهم في حياتك\nلا انت الي استفدت من شرحه ولا انت الي قدرت تنام بالكلاس … لانه اذا شافك نايم بيقومك\n\n**الكويزات :**والله عن نفسي ما كنت “اقدر” اركز معاه لان زي ما قال واحد من الشباب فوق … اجي مصحصح وابي افهم الدرس اليوم ومتحمس … ما اقعد 5 دقايق الا تلقاني احارب النوم … عاد الترم ذاك كنت متعقد من اللهجات السيئة حقت بعض المدرسين\nو كملت المصيبة في هذا المدرس … عموما … الكويزات راحت علي\nمع هذا كله كنت دايم حول الافرج … يعني غالبا الفصل كله يحس باحساسي … واحد او اثنين الي مرة دافرين >> موجودة بكل كلاس وما اظن من شرحه بل من المذاكرة ف البيت\n\nالمياجر:= الكويزات … حول الافرج دايما\n\nالفاينلات := المياجر\n\n**القريد النهائي:**c ~ d خليه ااااخر خياراتك دايما\n\n**الصوت:**من أبرد ما يكون مع اللهجة حقته … احلى كومبنيشن للنوم\n\nإضافات : هذا الي حصل معي … يمكن ما يحصل معاك … يمكن الغلط مني … بس حبيت اشارك برأيي", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1156373-ics381", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/el-sayed-el-alfy/98299/13", "user": "some001", "ts": 1357439432000, "tid": 98299, "pn": 13}}]}', 1357439432000, 1794826863, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-the_red_blue-ics381', 'stk-the_red_blue', 'ICS 381', 'doc', '{"docs": [{"id": "stk-dr-f98299", "n": "Dr. El-Sayed El-Alfy", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Ics 381: Ai\n\nالتحضير :\n\nيوميا بعد ما يخلص، ما يدقق بالتأخير، لكن السؤال متى يخلص؟ في بداية السمستر كان مستحيل يطلعك قبل لا يخلص و غاب أسبوع و صار يوميا ياخذ ما لا يقل عن 25 دقيقة و هو يقول احنا عندنا رصيد. ألعن أبو هالرصيد الي طول السنة ما خلص…\n\nطريقة الشرح :\n\nسلايدات و أحيانا عالسبورة، مثل ما قلت في رد سابق الآدمي منوم طبيعي، غير كذا الظاهر إنه أول مرة يدرس الكورس و مش متمكن منه، طول السمستر ما فهمت إلا الأشياء السهلة، الأمثلة بس، لكن الكونسبت غالبا يفتح الله\n\nالكويزات :\n\nسهلة\n\nالمياجر:\n\nأسئلته مباشرة و سهلة\n\nالفاينلات :\n\nكان صلخ الصراحة…\n\nالقريد النهائي:\n\nD\n\nالصوت:\n\nواضح مع وجود اكسنت مصري\n\nإضافات :\n\nبالنسبة للوقت تكلمت عنه في التحضير، تصحيحه بلا زيادة و لا نقصان، غير متفهم بتاتا للطلاب، أسلوبه جلف في مسألة التأجيل و التسليم، تسلم سوفت كوبي بدون هارد كوبي صفر، ما تسوي برزنتيشن البروجكت صفر. صوته منوم مغناطيسي مثل ما قلت من قبل… نصيحة لوجه الله لا تنزل هالكورس معاه.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1165262-ics381", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/el-sayed-el-alfy/98299/14", "user": "The_Red_Blue", "ts": 1358421934000, "tid": 98299, "pn": 14}}]}', 1358421934000, 1794826863, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-atsuko-ics381', 'stk-atsuko', 'ICS 381', 'doc', '{"docs": [{"id": "stk-dr-f98299", "n": "Dr. El-Sayed El-Alfy", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ترم 201 (اونلاين)\nICS 381\nما ازيد شي على كلام اللي فوقي, غير انه الدكتور ما كان يعطينا فييدباك على اختباراتنا, ما كنت تعرف فين كنت تجيب العيد, بس يعطيك الدرجة النهائية, المشكلة فيه مواضيع تكررت في الاختبارات اللي بعدها, ف كنا نحتاج الفييد باك.\nوما كان ناوي يعطينا الافرج حتى, بالقوة خليناه يحط الافرج.\nالدكتور بشكل عام سيئ في التعامل وفي الشرح وفي اختباراته, في التحضير كان يعتمد على زوم, مادري هل بيخصم على الغياب ولا لا. لكن على كلامه يقول اذا غيابك مو كثير او مو متكرر, ف ما راح يضرك, حتى التأخير. ف ممكن هذا الشي الوحيد الايجابي اللي فيه.\n\nرسميا اسوء دكتور درسني.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527348-ics381", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/el-sayed-el-alfy/98299/27", "user": "atsuko", "ts": 1609206580000, "tid": 98299, "pn": 27}}]}', 1609206580000, 1794826863, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user3083-ics381', 'stk-user3083', 'ICS 381', 'doc', '{"docs": [{"id": "stk-dr-f102388", "n": "Dr. S Arafat", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الكورس ics 381 سمستر 092\n\nالتحضير :\nتقريبا كل كلاس . واكثر حركة تقهرني فيه ياخذ سبع دقايق من نهاية كل كلاس… وما يحضر الا في السبع دقايق هذي… 😭 يعني اذا عندك كلاس بعيد غير جدولك من الان.\nطريقة الشرح :\nعلى قولة اخواننا بيييييييييييييييييييييييييض (بالعربي فاشل ) الله يشهد ان الكورس هذا من الكورسات اللي دخلتها وطلعتها وانا موب فاهم شي ولا ادري وش تتكلم عنه وهذا كان حال اغلب السكشن اللي احنا فيه…\nالكويزات :\nيسوي كم كويز بس للامانة سهلين…\nالمياجر:\nبرضو شي يقهر فيه يجيب لك سؤال سخيف جوابه سطر واحد وعليه 20% من درجة الاختبار :@ يعني اذا ما تعرف او نسيت الجواب راحت علك اغلب الدرجة وما يمديك تاخذ جزء منها (بالعربي يا اسود يا ابيض يا تجيب الدرجة كاملة او ما تجيب شي)\nالفاينلات :\nنفس المياجر\nالقريد النهائي:\nF---------\nالصوت:\nhypnotism\n😦\n\nإضافات :\n\nبدون اي نوع من انواع المبالغة اسوأ مدرس ics خذت معه على الاطلاق !\nواخيس قريد ics خذته عند الادمي هذا 😞\nلاحد يجيني ويقول اني حاقد عليه… والله ان الادمي هذا من جنبها\nاذا سألوه الطلاب وما عرف يجاوب جلس يقول انتو ما تنتبهون وما تراجعون !\nشرحه يقرا سلايدات باور بوينت نوووووووووووووووووووووووووووووووووم\nوهو ماشي في السلايدات وانت ما تدري الكورس اللي انت فيه ics ولا كمستري!\nبالعربي نصيحة لوجه الله اللي بي يفهم الكورس اللي هو فيه لا نزل معاه حتى لو بيتأخر…ترى الوضع معه جدا سيء 😞\n\nبالتوفيق لكل الشباب", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p785415-ics381", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/s-arafat/102388/4", "user": "user3083", "ts": 1297332579000, "tid": 102388, "pn": 4}}]}', 1297332579000, 1794826863, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mohammed_mag-ics381', 'stk-mohammed_mag', 'ICS 381', 'doc', '{"docs": [{"id": "stk-dr-f118625", "n": "Dr. Moataz Ahmed", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ICS381 T231\n\nالتحضير : يحضر آخر الكلاس ملف اكسل، مايخصم على التأخير عادي يحضرك لو جيت اخر دقيقه في الكلاس، جدا متسامح في موضوع الحضور\nطريقة الشرح : يشرح من خبرته، سلايداته جدا مختصره ومهم انك تركز معاه، بتكلم اكثر تحت عن هالشيء.\nالكويزات : سهله\nالمياجر: كومن\nالفاينلات : كومن\nالصوت: واضح جدا\nإضافات : الدكتور يمكن بدايه الترم يلمح لك اذا انت طالب self study وتشوف الكلاسات مالها فايده لا تحضر الا متأخر عادي، لكن انتبه من هالشغله لأن كلاسه جدا مهم وطبيعي تحصل بعض الاحيان في الاختبارات او المياجر يحطلك اسئله عن شغله شرحها بالكلاس بس مب بالسلايدات، كلاساته مفيده ويحب يتفاعل مع الطلاب ويحفظ الطلاب، واضح انه فاهم في المجال ويدرس فتره طويله جدا. مهم تحضرله بالكلاس علشان اذا خذيتها self study مرح يمديك تفهم على هالسلايدات المختصره، يعني بإختصار اذا خذيتها self study معاه بتعاني، بس اذا حضرت كلاساته وركزت، مايحتاج تذاكر شيء بالبيت حتى للفاينل.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1537182-ics381", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/moataz-ahmed/118625/10", "user": "Mohammed_Mag", "ts": 1704103708000, "tid": 118625, "pn": 10}}]}', 1704103708000, 1794826863, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-spacex-ics381', 'stk-spacex', 'ICS 381', 'doc', '{"docs": [{"id": "stk-dr-f186281", "n": "Dr. Moayad Alnammi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "التحضير:\nلا يأخذ الحضور، ويعتمد على السلايدات التي أعدها بشكل ممتاز، ولا يحب استخدام الكتاب.\n\nطريقة الشرح:\nشرحه رائع جدًا، ويجعل المادة سهلة الفهم بفضل أسلوبه الممتاز واحترافيته.\n\nالكويزات:\nسهلة إلى حدٍ ما ومباشرة.\n\nالمياجر:\nكانت المياجر والتقييمات تحديًا بسيطًا، لكنها قابلة للتعامل.\n\nالفاينلات:\nالفاينل كان أيضًا تحديًا لكن يمكن تجاوزه بالتحضير الجيد.\n\nالقريد النهائي:\nA+\n\nالصوت:\nصوته ممتاز مع لهجة إنجليزية رائعة تضيف جمالًا للشرح.\n\nإضافات:\n\nأفضل دكتور في القسم بأكمله.\nيهتم بك كإنسان، ويريد أن يساعدك على اكتشاف مسارك الوظيفي، ويعتبر العلاقة أكثر من مجرد علاقة طالب ومدرس.\nفي أحد الفصول، أتاح فرصة للحصول على 10 درجات إضافية كمكافأة، وهو ما يعادل درجتين إضافيتين على القريد النهائي!\nنظامه في التقييم يعتمد على درجات معيارية؛ مثلًا، A+ يبدأ من 92، وA من 85، وهكذا، مما جعل البونص مهمًا للغاية.\nإذا كانت هناك مادة ICS-381 ولم يكن هو المدرس لها، أنصحك بشدة أن تنتظر الفصل الذي يدرّس فيه المادة، لأنك ستحبها جدًا معه.\nهذا المدرس يُقدّر كثيرًا الطلاب الذين يتفاعلون معه، ويمكن أن يبني معك علاقة طويلة الأمد دون شروط، مما سيفيدك في جوانب أخرى من حياتك الجامعية.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1538887-ics381", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/moayad-alnammi/186281/2", "user": "spaceX", "ts": 1736801400366, "tid": 186281, "pn": 2}}]}', 1736801400366, 1794826863, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
